package dev.irisvisualizer.editor;

import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.*;

final class EditorShellPreviewTests {
    private static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}
    private static void check(boolean value,String message){if(!value)throw new AssertionError("Editor shell / preview UI: "+message);}
    private static void rejects(Runnable action){try{action.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("Expected invalid preview UI input");}
    private static void close(float actual,float expected,String message){check(Math.abs(actual-expected)<.02f,message);}
    static void run(Path temp)throws Exception{
        check(EditorShell.FILE_ACTIONS.equals(List.of("New","Open","Save","Import","Export")),"File menu has exactly the original brief's five ordered actions");for(String action:EditorShell.FILE_ACTIONS)check(EditorCommands.Action.file(action)!=null,"existing command routing remains authoritative");check(CommandPalette.entries().stream().filter(e->e.title().startsWith("File:")).count()==5,"palette agrees with the five-action File menu");try{EditorShell.FILE_ACTIONS.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){}
        for(float width:new float[]{0,1,320,640,960,1280,1920,3840})for(float height:new float[]{0,12,600,1080,2160})for(float header:new float[]{0,24,40}){
            var layout=EditorShell.layout(width,height,header);var left=layout.resources();var middle=layout.visualization();var right=layout.inspector();float top=Math.min(header,height);close(left.x(),0,"left edge");close(left.y(),top,"actual menu-height offset");close(middle.x(),left.width(),"no panel overlap/gap");close(right.x(),middle.x()+middle.width(),"right adjacency");close(right.x()+right.width(),width,"panels fill viewport");for(var pane:List.of(left,middle,right)){check(pane.width()>=0 && pane.height()>=0,"nonnegative minimized/narrow panel bounds");close(pane.y(),top,"shared panel top");close(pane.height()+top,height,"shared panel bottom");}if(width>=1280){check(left.width()<=320 && right.width()<=480 && middle.width()>=width-800,"large displays give remaining room to visualization");}
        }
        rejects(()->EditorShell.layout(-1,2,3));rejects(()->EditorShell.layout(1,Float.NaN,3));rejects(()->EditorShell.layout(1,2,Float.POSITIVE_INFINITY));
        var files=new LinkedHashMap<String,byte[]>();files.put("dimensions/one.json",bytes("{\"minHeight\":-64,\"maxHeight\":320,\"future\":9007199254740993}"));files.put("biomes/nested/a.json",bytes("{\"future\":9007199254740993}"));files.put("regions/nested/a.json",bytes("{}"));files.put("generators/a.json",bytes("{}"));files.put("expressions/a.json",bytes("{}"));files.put("structures/a.json",bytes("{}"));files.put("jigsaw-pools/a.json",bytes("{}"));files.put("jigsaw-pieces/a.json",bytes("{}"));files.put("objects/a.iob",new byte[]{0,-1});files.put("images/a.png",new byte[]{0,-1});files.put("image-maps/a.json",bytes("{}"));files.put("future/unknown.json",bytes("opaque preserved"));
        var pack=PackWorkspace.newPack(files);long revision=pack.revision(),resources=pack.resourceRevision(),saved=pack.saveRevision();int undo=pack.undoCount();var drafts=new InspectorDrafts();drafts.update("late","stored","typing");var session=new PreviewSession();
        var biome=session.select(pack,"biomes/nested/a.json");check(biome.kind()==PreviewSession.Kind.BIOME && biome.contextual() && biome.dimension().equals("dimensions/one.json") && biome.meaningful(PreviewSession.Mode.TWO_D) && biome.meaningful(PreviewSession.Mode.THREE_D),"single exact top-level dimension auto-context; nested resource inherits its family");var catalog=biome.dimensions();
        var extremes=session.configure(Long.toString(Long.MIN_VALUE),Integer.toString(Integer.MIN_VALUE),Integer.toString(Integer.MAX_VALUE));check(extremes.coordinates().seed()==Long.MIN_VALUE && extremes.coordinates().x()==Integer.MIN_VALUE && extremes.coordinates().z()==Integer.MAX_VALUE,"exact long seed and signed world coordinates");
        for(String bad:List.of("","1.5","1e3","+1","0x10","--1","9223372036854775808","-9223372036854775809","x".repeat(21),"1\n2")){rejects(()->session.configure(bad,"0","0"));check(session.select(pack,"biomes/nested/a.json").coordinates().equals(extremes.coordinates()),"invalid seed never changes applied preview settings");}rejects(()->session.configure("1","2147483648","0"));rejects(()->session.configure("1","0","-2147483649"));check(session.select(pack,"biomes/nested/a.json").coordinates().equals(extremes.coordinates()),"paired coordinates apply atomically");
        check(session.mode(PreviewSession.Mode.THREE_D).mode()==PreviewSession.Mode.THREE_D,"meaningful mode switch stores UI state");var object=session.select(pack,"objects/a.iob");check(object.kind()==PreviewSession.Kind.OBJECT && !object.contextual() && object.mode()==PreviewSession.Mode.THREE_D && !object.meaningful(PreviewSession.Mode.TWO_D),"object has only 3D; no irrelevant seed/coordinate controls");rejects(()->session.mode(PreviewSession.Mode.TWO_D));rejects(()->session.configure("1","2","3"));rejects(()->session.dimension("dimensions/one.json"));
        var image=session.select(pack,"images/a.png");check(image.image() && image.mode()==PreviewSession.Mode.TWO_D && !image.meaningful(PreviewSession.Mode.THREE_D),"original image only in 2D; previous 3D state cannot leak");rejects(()->session.mode(PreviewSession.Mode.THREE_D));var other=session.select(pack,"future/unknown.json");check(!other.meaningful(PreviewSession.Mode.TWO_D) && !other.meaningful(PreviewSession.Mode.THREE_D) && !other.image(),"unsupported resources have no meaningful tabs or stale image result");check(session.select(pack,"images/missing.png").kind()==PreviewSession.Kind.OTHER,"missing image cannot reuse prior image mode");
        for(String path:List.of("regions/nested/a.json","generators/a.json","expressions/a.json","structures/a.json","jigsaw-pools/a.json","jigsaw-pieces/a.json")){var view=session.select(pack,path);check(view.contextual() && view.dimension().equals("dimensions/one.json") && !view.unavailable().isEmpty(),"contextual resource gate explains unsupported backend "+path);}
        var returned=session.select(pack,"biomes/nested/a.json");check(returned.coordinates().equals(extremes.coordinates()) && returned.dimensions()==catalog,"context choices and metadata catalog survive resource navigation");check(pack.revision()==revision && pack.resourceRevision()==resources && pack.saveRevision()==saved && pack.undoCount()==undo && drafts.any(),"preview controls never mutate pack/Save/history/drafts");for(String path:files.keySet())check(Arrays.equals(pack.read(path),files.get(path)),"all original bytes unchanged "+path);
        pack.replace("biomes/nested/a.json",bytes("{}"));check(session.select(pack,"biomes/nested/a.json").dimensions()==catalog,"byte edits do not rebuild path-only dimension catalog");pack.undo();check(session.select(pack,"biomes/nested/a.json").coordinates().equals(extremes.coordinates()),"Undo retains UI-only preview settings");
        // Multiple contexts require an explicit choice; each context retains its own exact seed/coordinates.
        var multiFiles=new LinkedHashMap<>(files);multiFiles.put("dimensions/two.json",bytes("{}"));var multiple=PackWorkspace.newPack(multiFiles);var multi=new PreviewSession();var unresolved=multi.select(multiple,"biomes/nested/a.json");check(unresolved.dimension()==null && unresolved.unavailable().contains("Choose a dimension"),"no invented context when multiple dimensions exist");rejects(()->multi.configure("1","2","3"));multi.dimension("dimensions/two.json");var two=multi.configure(Long.toString(Long.MAX_VALUE),"12","-34");multi.dimension("dimensions/one.json");check(multi.select(multiple,"biomes/nested/a.json").coordinates().equals(new PreviewSession.Coordinates(0,0,0)),"new context gets independent UI defaults");multi.configure("7","8","9");check(multi.dimension("dimensions/two.json").coordinates().equals(two.coordinates()),"returning context retains its seed and coordinates");var selectedDimension=multi.select(multiple,"dimensions/one.json");check(selectedDimension.dimension().equals("dimensions/one.json") && selectedDimension.coordinates().seed()==7,"selected dimension is always its own context");rejects(()->multi.dimension("dimensions/two.json"));rejects(()->multi.dimension("dimensions/missing.json"));
        var noDimension=PackWorkspace.newPack(Map.of("biomes/a.json",bytes("{}"),"dimensions/nested/invalid.json",bytes("{}")));var empty=new PreviewSession().select(noDimension,"biomes/a.json");check(empty.dimensions().keys().isEmpty() && empty.dimension()==null,"nested dimension file is not a valid context");
        // Full bounded catalog is pageable, case/exact paths retained, and metadata-budget errors remain stable.
        var manyFiles=new LinkedHashMap<String,byte[]>();manyFiles.put("biomes/a.json",bytes("{}"));for(int i=0;i<451;i++)manyFiles.put(String.format(Locale.ROOT,"dimensions/d%03d.json",i),bytes("{}"));var many=PackWorkspace.newPack(manyFiles);var manySession=new PreviewSession();var choices=manySession.select(many,"biomes/a.json");var all=new ArrayList<String>();for(int page=0;page<3;page++)all.addAll(choices.dimensions().page("",page).entries());check(all.equals(choices.dimensions().keys()) && all.size()==451 && choices.dimensions().page("",Integer.MAX_VALUE).entries().size()==51,"all late dimension contexts reachable through bounded 200-row pages");check(manySession.dimension(all.getLast()).dimension().equals("dimensions/d450.json"),"exact late-page context selection");
        var budget=new PreviewSession(1,16_000_000);var blocked=budget.select(multiple,"biomes/nested/a.json");check(blocked.problem()!=null && blocked.dimension()==null && blocked.dimensions().keys().isEmpty() && budget.select(multiple,"biomes/nested/a.json").dimensions()==blocked.dimensions(),"context budget failure is stable and cached until metadata changes");var characters=new PreviewSession(10,"dimensions/one.json".length()-1);check(characters.select(pack,"biomes/nested/a.json").problem()!=null,"exact metadata character guard");check(budget.select(multiple,"images/a.png").image(),"context metadata errors do not disable the original image viewer");
        var replacement=PackWorkspace.newPack(files);check(session.select(replacement,"biomes/nested/a.json").coordinates().equals(new PreviewSession.Coordinates(0,0,0)),"workspace identity clears all preview choices");session.configure("9","10","11");session.clear();check(session.select(replacement,"biomes/nested/a.json").coordinates().seed()==0,"explicit clear releases UI state");
        // Preview context, seed and coordinates never become JSON overrides in saved/exported packs.
        session.configure(Long.toString(Long.MAX_VALUE),"13","-27");replacement.save(temp.resolve("shell-preview-save"));var retained=session.select(replacement,"biomes/nested/a.json");replacement.saveCopy(temp.resolve("shell-preview-copy"));replacement.saveAs(temp.resolve("shell-preview-as"));replacement.exportZip(temp.resolve("shell-preview.zip"));check(session.select(replacement,"biomes/nested/a.json").coordinates().equals(retained.coordinates()) && drafts.any(),"Save modes retain UI state and unrelated drafts");for(var reopened:List.of(PackWorkspace.open(temp.resolve("shell-preview-save")),PackWorkspace.open(temp.resolve("shell-preview-copy")),PackWorkspace.open(temp.resolve("shell-preview-as")),PackWorkspace.importZip(temp.resolve("shell-preview.zip")))){check(reopened.paths().equals(replacement.paths()),"no preview override files");for(String path:replacement.paths())check(Arrays.equals(reopened.read(path),replacement.read(path)),"exact saved source without preview overrides");}
        System.out.println("PASS: original-brief five-action File menu and contiguous responsive three-panel shell geometry, UI-only preview resource/mode eligibility with no stale image/3D mode, exact single/multiple/top-level dimension context choices and all 451 paged contexts, independent per-context signed-long seeds/atomic coordinates, stable metadata budget failures and owner/Undo/Save isolation, unchanged drafts/history and byte-exact Save/Copy/As/ZIP without preview overrides or native generation");
    }
}
